#!/usr/bin/env bash
# Generated by `ztmesh render`; do not edit. Registers the agent node alias and workloads.
# Safe to re-run: an entry that already exists is reported and skipped.
set -euo pipefail
register() {
  local out
  if out=$(timeout 30 "$@" 2>&1); then echo "$out"; return 0; fi
  if grep -qiE "AlreadyExists|similar entry already exists" <<<"$out"; then
    echo "already registered: $*" | cut -c1-200; return 0
  fi
  echo "$out" >&2; return 1
}
register kubectl -n spire exec spire-server-0 -c spire-server -- /opt/spire/bin/spire-server entry create -node -spiffeID spiffe://mesh.example/ns/spire/sa/spire-agent -selector k8s_psat:cluster:zt-demo -selector k8s_psat:agent_ns:spire -selector k8s_psat:agent_sa:spire-agent
register kubectl -n spire exec spire-server-0 -c spire-server -- /opt/spire/bin/spire-server entry create -spiffeID spiffe://mesh.example/ns/demo/sa/backend -parentID spiffe://mesh.example/ns/spire/sa/spire-agent -selector k8s:ns:demo -selector k8s:sa:backend -x509SVIDTTL 3600
register kubectl -n spire exec spire-server-0 -c spire-server -- /opt/spire/bin/spire-server entry create -spiffeID spiffe://mesh.example/ns/demo/sa/frontend -parentID spiffe://mesh.example/ns/spire/sa/spire-agent -selector k8s:ns:demo -selector k8s:sa:frontend -x509SVIDTTL 3600
